using System;using System.IO;using System.IO.Pipes;using System.Diagnostics;using System.Drawing;using System.Threading;using System.Windows.Forms;using System.Web.Script.Serialization;using System.Security.AccessControl;using System.Security.Principal;
static class Launcher{
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool created;using(var mutex=new Mutex(true,"Local\\LifeAC-Lighting-Host",out created)){
 if(args.Length==1&&args[0]=="--install"){if(!created){MessageBox.Show("Close LifeAC Lighting from its tray menu before installing.");return 1;}return Install();}
 if(!created){try{using(var p=new NamedPipeClientStream(".","LifeACLightingOpen",PipeDirection.Out)){p.Connect(1500);using(var w=new StreamWriter(p)){w.WriteLine("open");}}}catch{MessageBox.Show("LifeAC Lighting is already starting. Look for its tray icon.");}return 0;}
 using(var host=new Host())Application.Run(host);return 0;}}
 static int Install(){try{string source=AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\'),target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","LifeAC-Lighting","releases","0.1.0-"+DateTime.Now.ToString("yyyyMMddHHmmss"));if(source.Equals(target,StringComparison.OrdinalIgnoreCase)||target.StartsWith(source+"\\",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Install from an extracted folder outside the destination");Copy(source,target);
 string exe=Path.Combine(target,"LifeAC Lighting.exe"),programs=Environment.GetFolderPath(Environment.SpecialFolder.Programs),desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));foreach(string location in new[]{programs,desktop}){dynamic shortcut=shell.CreateShortcut(Path.Combine(location,"LifeAC Lighting.lnk"));shortcut.TargetPath=exe;shortcut.WorkingDirectory=target;shortcut.Description="LifeAC church lighting";shortcut.IconLocation=exe;shortcut.Save();}
 MessageBox.Show("LifeAC Lighting is installed for this Windows user. Your existing lighting software and drivers were not changed. Open the new shortcut when ready.","LifeAC Lighting");return 0;}catch(Exception e){MessageBox.Show("Installation failed ("+e.GetType().Name+"). You can still use the portable app from a writable extracted folder.");return 1;}}
 static void Copy(string source,string dest){Directory.CreateDirectory(dest);foreach(string file in Directory.GetFiles(source))File.Copy(file,Path.Combine(dest,Path.GetFileName(file)),false);foreach(string dir in Directory.GetDirectories(source)){if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)continue;Copy(dir,Path.Combine(dest,Path.GetFileName(dir)));}}
}
sealed class Host:Form{
 Process child;NotifyIcon tray;string url;bool quitting;readonly string root=AppDomain.CurrentDomain.BaseDirectory;readonly JavaScriptSerializer json=new JavaScriptSerializer();
 public Host(){ShowInTaskbar=false;WindowState=FormWindowState.Minimized;Opacity=0;var menu=new ContextMenuStrip();menu.Items.Add("Open LifeAC Lighting",null,(s,e)=>Open());menu.Items.Add("Open show / backups folder",null,(s,e)=>Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LifeAC-Lighting")){UseShellExecute=true}));menu.Items.Add("Stop lighting host",null,(s,e)=>Stop());
 tray=new NotifyIcon{Visible=true,Text="LifeAC Lighting — starting",ContextMenuStrip=menu};string icon=Path.Combine(root,"web","assets","lifeac.ico");tray.Icon=File.Exists(icon)?new Icon(icon):SystemIcons.Application;tray.DoubleClick+=(s,e)=>Open();Load+=(s,e)=>Start();FormClosing+=(s,e)=>{if(!quitting){e.Cancel=true;Hide();}};
 var security=new PipeSecurity();security.AddAccessRule(new PipeAccessRule(WindowsIdentity.GetCurrent().User,PipeAccessRights.FullControl,AccessControlType.Allow));new Thread(()=>{while(!quitting)try{using(var pipe=new NamedPipeServerStream("LifeACLightingOpen",PipeDirection.In,1,PipeTransmissionMode.Byte,PipeOptions.None,0,0,security)){pipe.WaitForConnection();using(var reader=new StreamReader(pipe))if(reader.ReadLine()=="open"&&!IsDisposed)BeginInvoke((Action)Open);}}catch{if(!quitting)Thread.Sleep(200);}}){IsBackground=true}.Start();}
 void Start(){try{var info=new ProcessStartInfo(Path.Combine(root,"runtime","node.exe"),"\""+Path.Combine(root,"src","server.mjs")+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=root,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};child=new Process{StartInfo=info,EnableRaisingEvents=true};string failure="";
 child.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)failure=e.Data.Contains("EADDRINUSE")?"The local port is already in use. Another instance or service may be running.":"The lighting host could not start. Check the supplied files and use the source validation notes.";};
 child.OutputDataReceived+=(s,e)=>{if(e.Data!=null&&e.Data.StartsWith("READY "))try{var d=json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(e.Data.Substring(6));url=d["url"];BeginInvoke((Action)(()=>{tray.Text="LifeAC Lighting — running";Open();Hide();}));}catch{}};
 child.Exited+=(s,e)=>{if(!quitting&&!IsDisposed)BeginInvoke((Action)(()=>{tray.Text="LifeAC Lighting — stopped";MessageBox.Show(failure.Length>0?failure:"The lighting host stopped. Physical output state is not confirmed. Restore normal control before services.","LifeAC Lighting");quitting=true;tray.Visible=false;Close();}));};child.Start();child.BeginOutputReadLine();child.BeginErrorReadLine();}catch(Exception e){quitting=true;MessageBox.Show("Cannot start LifeAC Lighting ("+e.GetType().Name+"). Extract the complete ZIP first.");Close();}}
 void Open(){if(url==null){tray.ShowBalloonTip(2500,"LifeAC Lighting","Starting the local lighting host…",ToolTipIcon.Info);return;}Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
 void Stop(){if(MessageBox.Show("Stop the lighting host and release USB? The device's standalone state after release is not automatically known.","LifeAC Lighting",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;quitting=true;try{if(child!=null&&!child.HasExited){child.StandardInput.WriteLine("stop");if(!child.WaitForExit(10000))child.Kill();}}catch{}tray.Visible=false;Close();}
 protected override void Dispose(bool disposing){if(disposing){if(tray!=null)tray.Dispose();if(child!=null)child.Dispose();}base.Dispose(disposing);}
}
